(四)、RFID 模組 
本組所使用的RFID 模組型號為RC522，其接腳共有SDA、SCK、MISO、MOSI、IRQ、
GND、RST、3.3V 等，如圖(⋩五)所示。此一模組即是本作品之感應機台，為一重要的訊號擷

取元件。當乘客有意坐博愛座時需先將其所持有之RFID 卡置於本感應機台之前，本感應機台將感應擷取該RFID 卡之內碼，然後傳送至Arduino 微控制器判斷該乘客之身分。此一RFID
卡與Arduino 微控制器之間的接線甚為重要，一㖎接錯，即無法正確判斷乘客身份，如此，本作品即無法發揮其功能，圖(⋩六)為RC522 RFID 模組與Arduino微控制器之間的接腳連線圖。 


圖(⋩五) RC522 RFID 模組之腳位圖 


圖(⋩六) RFID 模組與Arduino 微控制器之接腳連線圖 

三、軟體程式設計 
 軟體程式有如人體大腦，用以判斷事情之邏輯與程序，然後指揮身體各個器官依序工作。本作品共有LED 與喇叭兩個輸出元件以及RFID 感應機台與壓力開關兩個輸入元件， 
Arduino 微控制器首先接收RFID 感應機台與壓力開關之輸入訊號，判斷目前博愛座是否有人坐，該名乘客身份是否具有坐博愛座資格，若不是，則輸出訊號給LED 陣列與喇叭，以提醒該名乘客禮讓博愛座。基於這樣的邏輯，本組所撰寫之程式如下所示。 
首先，本程式會載入SPI.h 與RFID.h 兩個標頭檔，以便能夠利用其所提供之指令。接著定義常用腳位名稱與變數，方便程式被閱讀與撰寫。再接著⭋告所需之Arduino 輸出與輸入腳位，使這些腳位之功能得以正確。最後，在loop 含式裡撰寫讀卡程式、內碼判斷程式、壓力開關訊號讀取與判斷程式以及喇叭與LED 陣列啟閉程式。 

#include <SPI.h> 
#include <RFID.h> 
#define SS_PIN 10 
#define RST_PIN 9 
RFID rfid(SS_PIN,RST_PIN); 
int serNum[5]; serNum[5]陣列為RFID 卡號(第一區 至 第五區)的辨別 
int x , y=0 ,z=0; 
void setup() 
{ 
 pinMode(3,OUTPUT); 
 pinMode(6,OUTPUT); 
 pinMode(7,OUTPUT); 
 pinMode(8,OUTPUT); 
// pinMode(9,OUTPUT); 
 pinMode(9,INPUT); 
 Serial.begin(9600); 
 SPI.begin(); 
 rfid.init(); 
} 
void loop() 
{ 
 if(rfid.isCard()) 
 { 
 if(rfid.readCardSerial()) 讀取卡片卡號 
 { 
 serNum[0] = rfid.serNum[0]; 
 Serial.print(rfid.serNum[0],DEC); 卡片第一區卡號 
 Serial.print(" "); 
 Serial.print(rfid.serNum[1],DEC); 卡片第二區卡號 
 Serial.print(" "); 

 Serial.print(rfid.serNum[2],DEC); 卡片第三區卡號 
 Serial.print(" "); 
 Serial.print(rfid.serNum[3],DEC); 卡片第四區卡號 
 Serial.print(" "); 
 Serial.print(rfid.serNum[4],DEC); 卡片第五區卡號 
 Serial.println(""); 
 } 
 } 
 else if(!rfid.isCard()) 判斷是否讀取到卡片 
 { 
 serNum[0] = 0; 讓第一區卡號歸零(為了清除原本卡號) 
 } 
if(serNum[0] ==169 ) 判斷第一區卡號是否等於169 
 { 
 digitalWrite(6,LOW); 第6 腳 LED 不亮 
 digitalWrite(7,LOW); 第7 腳LED 不亮 
 digitalWrite(8,LOW); 第8 腳LED 不亮 
 x=1; x=1 是為了判斷按鈕按下後是否停止警報 
 noTone(3); 喇叭停止輸出 
 } 
 else if(serNum[0] !=169) 判斷第一區卡號是否不等於169 
 { 
 if(y==158 &&!digitalRead(9)) y 是否等於158 的目的為讀取到正確卡號 
後的延遲時間 
 { 
 x=0; 
 y=0; 
 } 
 else if(!digitalRead(9)) 
 y++; 

 if(rfid.readCardSerial()) 判斷是否讀取錯誤卡號 
 { 
 digitalWrite(6,HIGH); 
 digitalWrite(7,HIGH); 
 digitalWrite(8,HIGH); 
 tone(3,800); 
 delay(500); 
 digitalWrite(6,LOW); 
 digitalWrite(7,LOW); 
 digitalWrite(8,LOW); 
 noTone(3); 
 delay(500); 
 digitalWrite(6,HIGH); 
 digitalWrite(7,HIGH); 
 digitalWrite(8,HIGH); 
 tone(3,800); 
 delay(500); 
 digitalWrite(6,LOW); 
 digitalWrite(7,LOW); 
 digitalWrite(8,LOW); 
 noTone(3); 
 delay(500); 
 } 
 } 
 if(digitalRead(9)) 判斷開關是否按下 
 { 
 if(x==1) 
 { 
 digitalWrite(6,LOW); 
 digitalWrite(7,LOW); 

 digitalWrite(8,LOW); 
 } 
 else 
 { 
 digitalWrite(6,HIGH); 
 digitalWrite(7,HIGH); 
 digitalWrite(8,HIGH); 
 delay(100); 
 tone(3,800); 
 z=5; 設定z=5(z 的計算是判斷按鈕5 秒都沒被壓下後，則喇叭自動停止輸出) 
 } 
 delay(200); 
 } 
 else if(!digitalRead(9)) 
 { 
 if (z >0) 判斷z 是否大於0 
 { 
 delay(1000); 延遲1 秒 
 z--; z 減1 
 } 
 else if (z==0) 判斷z 是否等於0 
 { 
 noTone(3); 停止喇叭輸出 
 } 
 digitalWrite(6,HIGH); 
 digitalWrite(7,HIGH); 
 digitalWrite(8,HIGH); 
 } 
 }
